per_hop.query:
SELECT ?cityProfessor ?cityChurch WHERE {
  ?professor a dbo:Professor ;
             dbo:birthName "Nancy R. Howell" ;
             dbo:employer ?college .
  ?college dbo:city ?cityProfessor .
  ?church dbo:name "United Methodist Church of the Resurrection" ;
          dbo:city ?cityChurch .
  FILTER(CONTAINS(LCASE(STR(?cityProfessor)), "kansas") || CONTAINS(LCASE(STR(?cityChurch)), "kansas"))
}
